// One authoritative footprint reservation owns every parcel of a large facility.
export const SITE_SIZES={mall:[3,2],airport:[8,3],port:[3,2],spaceport:[3,3],dam:[3,1],reservoir:[2,2],arcology:[2,2],skyscraper:[2,2]};
export function siteTiles(city,t){const w=city.width||32;return Array.from({length:(t.siteWidth||1)*(t.siteHeight||1)},(_,i)=>t.id+i%(t.siteWidth||1)+Math.floor(i/(t.siteWidth||1))*w);}
export function inspectSite(city,id,type){const t=city.tiles[id],[width,height]=SITE_SIZES[type]||[1,1],w=city.width||32,h=city.height||32;if(!t||t.x+width>w||t.y+height>h)return {ok:false,message:'The full facility must fit within the map.'};const ids=siteTiles(city,{...t,siteWidth:width,siteHeight:height});if(ids.some(i=>city.tiles[i].siteRoot!==undefined||city.tiles[i].type!=='empty'))return {ok:false,message:`Reserve a clear ${width} × ${height} site first.`};if(ids.some(i=>city.tiles[i].terrain!==(type==='dam'?'water':'land')))return {ok:false,message:type==='dam'?'A dam requires a clear water span beside land.':'The full facility requires dry land.'};const levels=ids.map(i=>city.tiles[i].elevation||0);if(Math.max(...levels)-Math.min(...levels)>1)return {ok:false,message:'Level this site before placing a large facility.'};return {ok:true,ids,width,height};}
export function reserveSite(city,t,site){t.siteWidth=site.width;t.siteHeight=site.height;for(const id of site.ids)city.tiles[id].siteRoot=t.id;}
export function clearSite(city,t){for(const id of siteTiles(city,t)){delete city.tiles[id].siteRoot;}delete t.siteWidth;delete t.siteHeight;}
export function validateSites(city){const seen=new Set();for(const t of city.tiles){if(t.siteWidth===undefined&&t.siteHeight===undefined)continue;const spec=SITE_SIZES[t.type];if(!spec||t.siteWidth!==spec[0]||t.siteHeight!==spec[1]||t.x+t.siteWidth>(city.width||32)||t.y+t.siteHeight>(city.height||32))throw Error('Invalid facility footprint.');for(const id of siteTiles(city,t)){const child=city.tiles[id];if(!child||seen.has(id)||child.siteRoot!==t.id||id!==t.id&&child.type!=='empty')throw Error('Invalid facility reservation.');seen.add(id);}}for(const t of city.tiles)if(t.siteRoot!==undefined&&(!Number.isInteger(t.siteRoot)||!seen.has(t.id)))throw Error('Invalid reserved parcel.');}
